CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,price INT NOT NULL,image TEXT,sizes TEXT DEFAULT '',colors TEXT DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,product_id INT REFERENCES products(id),product_name TEXT,name TEXT NOT NULL,phone TEXT NOT NULL,wilaya TEXT NOT NULL,address TEXT,size TEXT,color TEXT,total INT,status TEXT NOT NULL DEFAULT 'new',created_at TIMESTAMPTZ DEFAULT now());
